/**
 * @description Builds the View request of one transaction: the request, the answer, the callback, the business
 * processing and the attempts, with the Files that hold full bodies. Reads in system mode; the caller
 * (IntegrationHubPreview.getExchange) has checked that the user can see the transaction.
 * @group Integration Hub
 */
public with sharing class IntegrationHubExchange {

    /** @description Shown to readers in place of the bodies. */
    @TestVisible
    private static final String HIDDEN = 'Bodies are shown to Integration Hub Admin users only.';

    /**
     * @description The exchange of one transaction.
     * @param transactionId the transaction
     * @return the exchange; Rerun is offered to admins only
     */
    public static IntegrationHubPreview.Exchange build(Id transactionId) {
        IH_Transaction__c t = (IH_Transaction__c) IntegrationHubData.queryFirst(
            'SELECT Id, Name, Event_Name__c, Direction__c, Status__c, Target_Name__c, Last_Attempt__c, CreatedDate, Request_Url__c, '
            + 'Request_Payload__c, Response_Body__c, Callback_Body__c, Http_Status_Code__c, Correlation_Id__c, Request_Id__c, '
            + 'Business_Status__c, Business_Result__c, Business_Error__c, Business_Runs__c, Event__r.Expects_Callback__c, '
            + 'Event__r.Business_Data_In_Response__c, Event__r.Response_Handler_Class__c, Event__r.Connection__r.Name, '
            + 'Event__r.Connection__r.Headers__c, Event__r.Connection__r.Connection_Type__c, Event__r.Connection__r.Auth_Class__c, '
            + 'Event__r.Auto_Retry_Max__c, Next_Retry_At__c, Auto_Retries__c FROM IH_Transaction__c WHERE Id = :id LIMIT 1',
            new Map<String, Object>{ 'id' => transactionId });
        if (t == null) {
            throw IntegrationHubPreview.auraError('You cannot open this transaction.');
        }
        IntegrationHubPreview.Exchange x = new IntegrationHubPreview.Exchange();
        x.transactionId = t.Id;
        x.name = t.Name;
        x.eventKey = t.Event_Name__c;
        x.direction = t.Direction__c;
        x.status = t.Status__c;
        x.connectionName = t.Event__r?.Connection__r?.Name;
        x.sentAt = t.Last_Attempt__c == null ? t.CreatedDate : t.Last_Attempt__c;
        x.httpStatus = t.Http_Status_Code__c == null ? null : t.Http_Status_Code__c.intValue();
        x.expectsCallback = t.Event__r?.Expects_Callback__c == true;
        Boolean admin = IntegrationHubPreview.isAdmin();
        request(x, t);
        if (admin) {
            bodies(x, t);
        } else {
            hideBodies(x);
        }
        business(x, t, admin);
        x.attempts = attempts(t.Id);
        x.nextRetryAt = t.Status__c == IntegrationHub.STATUS_FAILED ? t.Next_Retry_At__c : null;
        x.autoRetries = t.Auto_Retries__c == null ? 0 : t.Auto_Retries__c.intValue();
        x.autoRetryMax = IntegrationHubRetryPlan.maxRetries(t.Event__r);
        return x;
    }

    private static void request(IntegrationHubPreview.Exchange x, IH_Transaction__c t) {
        if (t.Direction__c == IntegrationHub.INBOUND) {
            x.requestUrl = 'POST ' + IntegrationHubPreview.REST_BASE + t.Event_Name__c;
            x.requestHeaders = new List<IntegrationHubPreview.Header>{
                new IntegrationHubPreview.Header('Content-Type', 'application/json'),
                new IntegrationHubPreview.Header('X-Request-Id', t.Request_Id__c == null ? '(none sent)' : t.Request_Id__c)
            };
        } else {
            x.requestUrl = t.Request_Url__c;
            x.requestHeaders = IntegrationHubPreview.sendHeaders(
                String.isBlank(t.Correlation_Id__c) ? String.valueOf(t.Id) : t.Correlation_Id__c, t.Event__r?.Connection__r);
        }
    }

    private static void bodies(IntegrationHubPreview.Exchange x, IH_Transaction__c t) {
        Map<String, Id> files = IntegrationHubBodyFiles.fileIds(t.Id);
        x.requestBody = pretty(t.Request_Payload__c);
        x.requestCut = IntegrationHubBodyFiles.isCut(t.Request_Payload__c);
        x.requestFileId = files.get(IntegrationHubBodyFiles.REQUEST_PREFIX);
        x.responseBody = pretty(t.Response_Body__c);
        x.responseCut = IntegrationHubBodyFiles.isCut(t.Response_Body__c);
        x.responseFileId = files.get(IntegrationHubBodyFiles.RESPONSE_PREFIX);
        x.callbackBody = pretty(t.Callback_Body__c);
        x.callbackCut = IntegrationHubBodyFiles.isCut(t.Callback_Body__c);
        x.callbackFileId = files.get(IntegrationHubBodyFiles.CALLBACK_PREFIX);
    }

    /**
     * @description Readers have no access to the body fields (Integration Hub Read gives none), so View request shows
     * them a note instead of the request, answer and callback bodies.
     * @param x the exchange
     */
    @TestVisible
    private static void hideBodies(IntegrationHubPreview.Exchange x) {
        x.requestBody = HIDDEN;
        x.responseBody = HIDDEN;
        x.callbackBody = HIDDEN;
        x.requestCut = false;
        x.responseCut = false;
        x.callbackCut = false;
    }

    private static void business(IntegrationHubPreview.Exchange x, IH_Transaction__c t, Boolean admin) {
        x.businessData = t.Event__r?.Business_Data_In_Response__c == true || t.Business_Status__c != null;
        x.handlerClass = t.Event__r?.Response_Handler_Class__c;
        x.businessStatus = t.Business_Status__c;
        x.businessResult = t.Business_Result__c;
        x.businessError = t.Business_Error__c;
        x.businessRuns = t.Business_Runs__c == null ? 0 : t.Business_Runs__c.intValue();
        x.canRerun = admin && t.Business_Status__c == IntegrationHubBusiness.FAILED;
    }

    private static List<IntegrationHubPreview.AttemptRow> attempts(Id transactionId) {
        List<IntegrationHubPreview.AttemptRow> rows = new List<IntegrationHubPreview.AttemptRow>();
        for (IH_Attempt__c a : (List<IH_Attempt__c>) IntegrationHubData.query(
                'SELECT Attempted_At__c, Kind__c, Http_Status_Code__c, Outcome__c, Payload_Used__c, Error_Summary__c FROM IH_Attempt__c '
                + 'WHERE Transaction__c = :id ORDER BY Attempted_At__c ASC NULLS LAST, CreatedDate ASC LIMIT 200',
                new Map<String, Object>{ 'id' => transactionId })) {
            IntegrationHubPreview.AttemptRow row = new IntegrationHubPreview.AttemptRow();
            row.n = rows.size() + 1;
            row.at = a.Attempted_At__c;
            row.kind = a.Kind__c == null ? 'Send' : a.Kind__c;
            row.httpStatus = a.Http_Status_Code__c == null ? null : a.Http_Status_Code__c.intValue();
            row.outcome = a.Outcome__c;
            row.payloadUsed = a.Payload_Used__c;
            row.error = a.Error_Summary__c;
            rows.add(row);
        }
        return rows;
    }

    /**
     * @description JSON text pretty-printed; other text unchanged.
     * @param text the text
     * @return the pretty JSON, or the text
     */
    public static String pretty(String text) {
        try {
            return String.isBlank(text) ? text : JSON.serializePretty(JSON.deserializeUntyped(text));
        } catch (JSONException e) {
            return text;
        }
    }
}
